def carrier_accepted(shipment, accepted_at):
    """Called when the carrier accepts a parcel for onward transport."""
    shipment["completed_at"] = accepted_at


def delivery_confirmed(shipment, received_at):
    """Called when the recipient's delivery receipt arrives."""
    shipment["completed_at"] = received_at


def stored_row(shipment):
    # This is the complete persisted representation; writer identity is not saved.
    return {
        "id": shipment["id"],
        "completed_at": shipment.get("completed_at"),
    }


def public_response(shipment):
    # External clients consume this response.
    return {
        "id": shipment["id"],
        "completedAt": shipment.get("completed_at"),
    }


def customer_status(shipment):
    if shipment.get("completed_at") is not None:
        return f"Delivered at {shipment['completed_at']}"
    return "In transit"
